  function formatBytes(value){const bytes=Number(value)||0;if(!bytes)return '';if(bytes<1024*1024)return Math.max(1,Math.round(bytes/1024))+' KB';return(bytes/(1024*1024)).toFixed(bytes<10*1024*1024?1:0)+' MB';}
