  function closePrompt(force){if(force)return;const popup=document.getElementById('vyGithubUpdatePrompt');if(!popup)return;const finish=()=>{popup.remove();document.body.classList.remove('subscription-dialog-open');};try{if(window.vyaparMotion)window.vyaparMotion.closeOverlay(popup,finish);else finish();}catch(_){finish();}}
  function showUpdatePrompt(info){document.getElementById('vy670UpdatePrompt')?.remove();document.getElementById('vyGithubUpdatePrompt')?.remove();const popup=document.createElement('div');popup.id='vyGithubUpdatePrompt';popup.className='subscription-overlay vy-github-update-overlay';popup.innerHTML=`<section class="subscription-dialog vy-github-update-dialog" role="dialog" aria-modal="true"><div class="vy-update-icon">↑</div><div class="vy-update-heading"><small>${info.force?'REQUIRED UPDATE':'UPDATE AVAILABLE'}</small><h2>Vyapar AI ${escapeHtml(info.versionName||'')}</h2><p>${info.force?'This update is required to continue safely.':'A newer approved GitHub release is ready.'}</p></div><div class="vy-update-notes">${notesHtml(info.releaseNotes)}</div><div class="vy-update-progress" data-update-progress hidden><div><span data-update-phase>Preparing update…</span><b data-update-percent></b></div><progress max="100" value="0" data-update-bar></progress><small data-update-size></small></div><div class="vy-update-actions">${info.force?'':'<button class="subscription-dialog-secondary" type="button" data-update-later>Later</button>'}<button class="subscription-dialog-primary" type="button" data-update-install>Download & install</button></div></section>`;popup.querySelector('[data-update-later]')?.addEventListener('click',()=>closePrompt(false));popup.querySelector('[data-update-install]')?.addEventListener('click',()=>startInstall(info));popup.addEventListener('click',e=>{if(e.target===popup&&!info.force)closePrompt(false);});document.body.appendChild(popup);document.body.classList.add('subscription-dialog-open');try{if(window.vyaparMotion)window.vyaparMotion.openOverlay(popup);}catch(_){}setTimeout(()=>popup.querySelector('[data-update-install]')?.focus(),0);}
  function startInstall(info){const popup=document.getElementById('vyGithubUpdatePrompt'),button=popup?.querySelector('[data-update-install]'),progress=popup?.querySelector('[data-update-progress]');if(button){button.disabled=true;button.textContent='Preparing…';}if(progress)progress.hidden=false;if(nativeUpdaterAvailable()){try{AndroidApp.downloadAndInstallUpdate(JSON.stringify(info));return;}catch(_){}}if(info.apkUrl){toastMessage('Opening the approved APK download.','success');try{if(window.AndroidApp&&typeof AndroidApp.openExternalUrl==='function')AndroidApp.openExternalUrl(info.apkUrl);else window.open(info.apkUrl,'_blank','noopener');}catch(_){}}else onNativeError({message:'The approved APK download link is missing.',visible:true});}
  function onNativeInfo(raw){const manual=Boolean(raw?.manual)||manualRequested,info=handleInfo(raw,manual),resolve=window.__vyaparUpdateNativeResolve;delete window.__vyaparUpdateNativeResolve;if(typeof resolve==='function')resolve(info);}
  function onNativeProgress(raw){const popup=document.getElementById('vyGithubUpdatePrompt');if(!popup)return;const progress=popup.querySelector('[data-update-progress]');if(progress)progress.hidden=false;const percent=Number(raw?.percent),bar=popup.querySelector('[data-update-bar]'),pct=popup.querySelector('[data-update-percent]'),phase=popup.querySelector('[data-update-phase]'),size=popup.querySelector('[data-update-size]'),button=popup.querySelector('[data-update-install]');if(bar&&Number.isFinite(percent)&&percent>=0)bar.value=Math.max(0,Math.min(100,percent));if(pct)pct.textContent=Number.isFinite(percent)&&percent>=0?Math.round(percent)+'%':'';if(phase)phase.textContent=raw?.phase==='verified'?'Update verified':'Downloading securely…';if(size){const done=formatBytes(raw?.bytes),total=formatBytes(raw?.total);size.textContent=total?`${done} of ${total}`:done;}if(button)button.textContent=raw?.phase==='verified'?'Opening installer…':'Downloading…';}
