  function renderUpdateCard(forcedStatus){const card=document.getElementById('fs607Settings');if(!card)return;if(card.dataset.githubUpdaterReady==='1'&&!forcedStatus){updateCardValues(card);return;}card.dataset.githubUpdaterReady='1';card.classList.add('vy-github-update-card');card.innerHTML=`<div class="settings-section-heading vy-update-card-heading"><div><span class="settings-kicker">APP UPDATE</span><h2>GitHub updates</h2><p class="muted">Securely checks only the approved Vyapar AI update manifest.</p></div><div class="settings-section-icon">↑</div></div><div class="vy-update-version-grid"><div><small>Current version</small><b data-update-current>—</b></div><div><small>Latest approved</small><b data-update-latest>—</b></div></div><div class="vy-update-status-row"><span><b data-update-status>${escapeHtml(forcedStatus||'Ready to check')}</b><small data-update-checked>Not checked yet</small></span><button class="btn" type="button" data-update-check>Check now</button></div><label class="vy-update-auto-row"><span><b>Automatic update checks</b><small>Checks at most every 12 hours. Updates are never installed without your confirmation.</small></span><span class="vy675-switch"><input type="checkbox" data-update-auto><span></span></span></label>`;card.querySelector('[data-update-check]')?.addEventListener('click',()=>checkForUpdate(true));card.querySelector('[data-update-auto]')?.addEventListener('change',e=>setAutoEnabled(Boolean(e.target.checked)));updateCardValues(card,forcedStatus);}
